# Probe for #76 design: what does TODAY's assemble render for a PLAN-shaped manifest?
# Read-only against the repo; builds a scratch store only. Not repo code.
param([string]$Root)

if (Test-Path $Root) { Remove-Item -Recurse -Force -Confirm:$false $Root }
New-Item -ItemType Directory -Force -Path $Root | Out-Null

function Write-Rec($dir, $name, $obj) {
  $d = Join-Path $Root $dir
  New-Item -ItemType Directory -Force -Path $d | Out-Null
  $json = $obj | ConvertTo-Json -Depth 10 -Compress
  [System.IO.File]::WriteAllText((Join-Path $d $name), $json, (New-Object System.Text.UTF8Encoding($false)))
}

# The PLAN manifest: 4 declared members.
#   carA  - dispatched AND returned  (fulfilled car)
#   gateA - dispatched AND returned  (fulfilled gate, outcome APPROVE)  <- does the GATES lane fill?
#   carB  - dispatched only          (in flight)
#   gateB - NO record at all         (planned, never launched -> the completeness assertion)
$manifest = [ordered]@{
  schema  = 'starcar-artifact/1'
  kind    = 'intent'
  subject = 'train:probe-76'
  session_id = '00000000-0000-0000-0000-000000000076'
  at      = '2026-07-27T12:00:00Z'
  manifest = [ordered]@{
    title   = 'Probe 76: plan-shaped manifest'
    tickets = @('#76')
    members = @(
      [ordered]@{ subject = 'carA';  role = 'car' },
      [ordered]@{ subject = 'gateA'; role = 'gate'; gate = 'car-review r1' },
      [ordered]@{ subject = 'carB';  role = 'car' },
      [ordered]@{ subject = 'gateB'; role = 'gate'; gate = 'car-review r2' }
    )
  }
  normalisation = @()
}
Write-Rec 'train-probe-76' 'intent-20260727T120000Z.json' $manifest

function Disp($subj, $at) {
  [ordered]@{ schema='starcar-artifact/1'; kind='dispatched'; subject=$subj; session_id='00000000-0000-0000-0000-000000000076';
              at=$at; budget=1800.0; model='claude-sonnet-5'; subject_basis='runtime-id'; producer='probe/1'; normalisation=@() }
}
function Ret($subj, $at, $outcome, $taskId) {
  [ordered]@{ schema='starcar-artifact/1'; kind='returned'; subject=$subj; session_id='00000000-0000-0000-0000-000000000076';
              at=$at; outcome=$outcome; findings='probe'; abstract='probe record'; subject_basis='runtime-id';
              task_id=$taskId; producer='probe/1'; normalisation=@() }
}

