# Integrity uses the repo's OWN Get-Sha256Hex (scripts/Artifact.psm1) over the compact
# canonical body, exactly as Produce-Artifact.ps1:363-365 does - never a second copy of
# the hashing rule.
param([string]$Root)

Import-Module C:\Users\Chris\git\starcar\scripts\Artifact.psm1 -Force

if (Test-Path $Root) { Remove-Item -Recurse -Force -Confirm:$false $Root }
New-Item -ItemType Directory -Force -Path $Root | Out-Null

function Seal($rec) {
  $bodyJson = $rec | ConvertTo-Json -Depth 20 -Compress
  $rec['integrity'] = 'sha256:' + (Get-Sha256Hex $bodyJson)
  return $rec
}

function Write-Rec($dir, $name, $obj) {
  $d = Join-Path $Root $dir
  New-Item -ItemType Directory -Force -Path $d | Out-Null
  $json = $obj | ConvertTo-Json -Depth 20 -Compress
  [System.IO.File]::WriteAllText((Join-Path $d $name), $json, (New-Object System.Text.UTF8Encoding($false)))
}

